package com.medtrack.supplier.dto; import com.medtrack.supplier.entity.Supplier; import java.util.UUID; public record SupplierResponse(UUID id,String name,String code,String contactEmail,String contactPhone,String address){public static SupplierResponse of(Supplier s){return new SupplierResponse(s.getId(),s.getName(),s.getCode(),s.getContactEmail(),s.getContactPhone(),s.getAddress());}}
